# Edition 2, items batch 5: scrolls, ammunition, rods, staffs, wands, and artifacts.
# (name, category, rarity, attunement, text)
A = "Requires Attunement"
AS = "Requires Attunement by a Spellcaster"
ITEMS = [
# ================= SCROLLS =================
("Twin Letter Scrolls", "Scroll", "Common", None, "These two scrolls come as a pair. Words written on one appear on the other within 1 minute, as long as both are on the same plane of existence. Each scroll holds about 200 words before it is full."),
("Hearth Recipe Scroll", "Scroll", "Common", None, "Read this recipe aloud while you cook a meal. The meal tastes excellent whatever went into it, and it stays fresh for 3 days. The scroll can be used once each day."),
("Scroll of the Shared Map", "Scroll", "Uncommon", None, "As a Magic action, you read this scroll while you hold a map. Up to six creatures within 30 feet of you who can see the map remember it perfectly for 7 days. The scroll then turns to dust."),
("Scroll of the Untied Knot", "Scroll", "Uncommon", None, "When you or a creature you can see within 30 feet of you has the Grappled or Restrained condition, you can take a Reaction to read this scroll. The condition ends on that creature. The scroll then turns to dust."),
("Scroll of Quiet Passage", "Scroll", "Uncommon", None, "As a Magic action, you read this scroll in a whisper. For 10 minutes, you and up to five creatures within 30 feet of you make no sound when you move, and you have Advantage on Dexterity (Stealth) checks. The scroll then turns to dust."),
("Scroll of the Iron Hour", "Scroll", "Rare", None, "As a Magic action, you read this scroll aloud. For 1 minute, you and up to five creatures of your choice within 30 feet of you have Resistance to Bludgeoning, Piercing, and Slashing damage. The scroll then turns to dust."),
("Scroll of the Second Breath", "Scroll", "Rare", None, "When a creature you can see within 30 feet of you dies, you can take a Reaction to read this scroll. You can also read it as a Magic action on a creature within 30 feet of you that died within the last minute. The creature returns to life with 1 Hit Point, unless it died of old age or is missing a part of its body that it needs to live. The scroll then turns to dust."),
("Scroll of the Many Doors", "Scroll", "Rare", None, "As a Magic action, you read this scroll aloud. You and up to five willing creatures within 30 feet of you can each teleport up to 60 feet to an unoccupied space that the creature can see. The scroll then turns to dust."),
("Scroll of the Severed Bond", "Scroll", "Very Rare", None, "As a Magic action, you read this scroll and touch a creature. Each curse on the creature ends, and the creature is freed from the Charmed and Frightened conditions and from possession. If a creature of the Celestial, Elemental, Fey, Fiend, or Undead type caused one of these effects, that creature is pushed out of the target's body and can't affect the target in the same way for 24 hours. The scroll then turns to dust."),
("Scroll of the Last Refuge", "Scroll", "Legendary", None, "As a Magic action, you read this scroll aloud while touching a door. You cast Demiplane, but the shadowy door stays for 7 days instead of 1 hour. While it lasts, only you and the creatures you name when you read the scroll can open it. The scroll then turns to dust."),
# ================= AMMUNITION =================
("Rope-Trailing Arrow", "Ammunition", "Common", None, "When fired, this arrow trails 50 feet of thin silk cord from a ring on its shaft. The cord is tied to the arrow and holds up to 200 pounds. Found in bundles of 1d4 + 1."),
("Arrow of the Echoing Call", "Ammunition", "Uncommon", None, "When this arrow hits a surface or a creature, it releases a loud call, such as a shout, a horn, or the roar of a beast, that repeats for 1 minute. Creatures within 30 feet of the arrow have Disadvantage on Wisdom (Perception) checks that rely on hearing. Found in bundles of 1d4."),
("Glass Bolt of Frost", "Ammunition", "Uncommon", None, "On a hit, the target takes an extra 2d6 Cold damage. Whether it hits or misses, a 10-foot square of ice forms where the bolt lands and lasts for 1 minute. The square is Difficult Terrain. Found in bundles of 1d4."),
("Arrow of the Marked Quarry", "Ammunition", "Rare", None, "On a hit, the target is marked for 1 hour. While it is marked, you always know the direction and the distance to it if it is within 1 mile of you, and your weapon attacks against it deal an extra 1d6 damage. The arrow then crumbles."),
("Bolt of Unseen Flight", "Ammunition", "Rare", None, "This bolt is Invisible in flight. If you are hidden when you make an attack with it, you stay hidden whether the attack hits or misses, and the target doesn't learn where the attack came from. Found in bundles of 1d4."),
("Arrow of the Bound Storm", "Ammunition", "Very Rare", None, "On a hit, the target takes an extra 4d10 Lightning damage. The lightning then leaps to up to two other creatures of your choice within 30 feet of the target. Each makes a DC 17 Dexterity save, taking 4d10 Lightning damage on a failed save or half as much on a successful one. The arrow is destroyed."),
("Sling Stone of Stillness", "Ammunition", "Very Rare", None, "On a hit, the target makes a DC 17 Wisdom save or has the Paralyzed condition for 1 minute. It repeats the save at the end of each of its turns, ending the effect on itself on a success. The stone then crumbles."),
("Arrow of the Falling Star", "Ammunition", "Legendary", None, "When you hit a creature with this arrow, or it strikes a point within the weapon's range, it explodes like a meteor. Each creature in a 40-foot-radius Sphere centered on that point makes a DC 19 Dexterity save. A creature takes 10d6 Fire damage and 10d6 Bludgeoning damage on a failed save, or half as much damage on a successful one. The arrow is destroyed."),
# ================= RODS =================
("Rod of Kindled Courage", "Rod", "Uncommon", A, "This rod has 3 charges and regains all expended charges daily at dawn. While holding it, you can expend 1 charge to cast Heroism (save DC 13) from it."),
("Rod of the Watchful Ward", "Rod", "Rare", A, "Once per dawn, you can use this rod to cast Glyph of Warding (save DC 15) without material components. While you hold the rod, you know when one of your glyphs is triggered, if you are on the same plane."),
("Rod of the Jailer's Key", "Rod", "Rare", A, "This iron rod has 3 charges and regains all expended charges daily at dawn. While holding it, you can expend 1 charge to cast Knock or Arcane Lock from it, or 2 charges to cast Hold Person (save DC 15) from it."),
("Rod of Ashes", "Rod", "Very Rare", A, "While holding this charred rod, you have Resistance to Fire and Poison damage. Once per dawn, you can cast Cloudkill (save DC 17) from it."),
("Rod of the Shepherd King", "Rod", "Very Rare", A, "This rod is topped with a silver crook. Once per dawn, you can cast Mass Suggestion (save DC 17) from it."),
("Rod of the Locked Room", "Rod", "Legendary", A, "Once per dawn, you can point this rod at a point you can see within 100 feet and cast Forcecage (save DC 19) from it, without material components."),
# ================= STAFFS =================
("Staff of Kindling", "Staff", "Uncommon", AS, "This blackened staff can be wielded as a Quarterstaff. It has 5 charges and regains 1d4 + 1 expended charges daily at dawn. While holding it, you can expend 1 charge to cast Burning Hands (save DC 13) from it, or 2 charges to cast Flaming Sphere (save DC 13) from it."),
("Staff of the Gravewind", "Staff", "Rare", AS, "This staff of grey wood can be wielded as a Quarterstaff. It has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 2 charges to cast Darkness from it, or 3 charges to cast Fear (save DC 15) from it."),
("Staff of the Ninefold Gate", "Staff", "Very Rare", AS, "This staff is a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. It has 10 charges and regains 1d6 + 4 expended charges daily at dawn. While holding it, you can expend charges to cast one of the following spells from it: Misty Step (1 charge), Dimension Door (3 charges), or Teleportation Circle (5 charges)."),
("Staff of the Long Winter", "Staff", "Very Rare", AS, "This staff of blue-white wood is a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you have Resistance to Cold damage. It has 10 charges and regains 1d6 + 4 expended charges daily at dawn. You can expend charges to cast one of the following spells from it (save DC 17): Ice Storm (4 charges), Cone of Cold (5 charges), or Wall of Ice (6 charges)."),
("Staff of the Unbound Sky", "Staff", "Legendary", AS, "This staff is a magic Quarterstaff that grants a +3 bonus to attack rolls and damage rolls made with it. While holding it, you have Resistance to Lightning and Thunder damage. It has 20 charges and regains 2d8 + 4 expended charges daily at dawn. You can expend charges to cast one of the following spells from it (save DC 18): Fly (3 charges), Chain Lightning (6 charges), Control Weather (8 charges), or Storm of Vengeance (9 charges)."),
# ================= WANDS =================
("Wand of the Conductor", "Wand", "Common", None, "While you hold this slim baton, you can wave it to make music that you can hear within 30 feet of you louder or softer, as you choose."),
("Wand of Silver Bells", "Wand", "Uncommon", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 1 charge to cast Healing Word from it. A tiny bell rings when you do."),
("Wand of Stinking Mist", "Wand", "Rare", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 3 charges to cast Stinking Cloud (save DC 15) from it."),
("Wand of the Iron Bar", "Wand", "Rare", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 2 charges to cast Hold Person (save DC 15) from it. For each additional charge you expend, the spell's level increases by 1, to a maximum of level 4."),
("Wand of the Hollow Mind", "Wand", "Very Rare", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 2 charges to cast Suggestion (save DC 17) from it, or 5 charges to cast Dominate Person (save DC 17) from it."),
("Wand of Seven Colors", "Wand", "Legendary", AS, "This wand of rainbow crystal has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 7 charges to cast Prismatic Spray (save DC 18) from it, or 1 charge to cast Color Spray from it."),
# ================= ARTIFACTS =================
("The Lantern of the First Dawn", "Wondrous Item", "Artifact", A, "This brass lantern holds a flame that was lit, the stories say, by the first sunrise. It sheds sunlight in a 60-foot radius and Dim Light for an additional 60 feet, and it can't be put out. Dawnward: while you are attuned to it, you have Resistance to Necrotic and Radiant damage, and Fiends and Undead in its Bright Light can't regain Hit Points. Charges: the lantern has 7 charges and regains 1d6 + 1 expended charges daily at dawn. You can expend charges to cast one of the following spells from it (save DC 19): Daylight (1 charge), Sunbeam (4 charges), or Sunburst (7 charges). The First Morning: once per 7 days, you can raise the lantern as a Magic action. Each Undead of CR 10 or lower within 60 feet of you that can see the lantern makes a DC 19 Wisdom save. On a failed save, it is destroyed. On a successful save, it takes 10d10 Radiant damage. Destroying the Lantern: the lantern goes out forever only if it is carried to a place that has never seen light and left there for a year and a day."),
("The Chalice of the Second Spring", "Wondrous Item", "Artifact", A, "This plain clay cup is always damp, and it smells of rain on new leaves. Green Hand: while you are attuned to it, you can cast Plant Growth and Speak with Plants from it at will. Charges: the chalice has 7 charges and regains 1d6 + 1 expended charges daily at dawn. You can expend charges to cast one of the following spells from it: Revivify (3 charges), Mass Cure Wounds (5 charges), or Heal (6 charges). Second Spring: once per year, you can fill the chalice with water and pour it onto the ground at dusk. At dawn, the land within 10 miles of that spot is healed of blight, poison, and magical ruin, and crops there grow as if a full season had passed. Curse: while you are attuned to the chalice, you must spend at least 4 hours in sunlight each day, or you gain 1 Exhaustion level at the next dawn. Destroying the Chalice: the chalice breaks only if it is filled with water from a land where nothing has ever grown."),
("The Tidebell", "Wondrous Item", "Artifact", A, "This green bronze bell was cast for a drowned temple, and the sea still answers it. Child of the Deep: while you are attuned to it, you can breathe water, you have a Swim Speed of 60 feet, and you have Resistance to Cold damage. Charges: the bell has 10 charges and regains 1d6 + 4 expended charges daily at dawn. As a Magic action, you can ring it and expend charges to cast one of the following spells from it (save DC 19): Control Water (4 charges), Conjure Elemental as a water elemental (5 charges), or Tsunami (8 charges). Curse: each time you use the Tsunami property, roll a d6. On a 1, a sea creature of CR 15 or lower comes to find the bell within 24 hours. Destroying the Bell: the bell breaks only if it is rung at the bottom of the deepest trench in the sea, where no sound can travel."),
("The Nameless Blade", "Weapon (Longsword)", "Artifact", A, "This black longsword has no maker's mark, and no one remembers its name. You gain a +3 bonus to attack rolls and damage rolls made with it, and it deals an extra 2d6 Necrotic damage on a hit. Takes Names: when you reduce a creature to 0 Hit Points with it, you learn the creature's true name and one secret it kept. A creature killed by the blade can be returned to life only by the Wish or True Resurrection spell. Spoken Name: once per dawn, as a Bonus Action, you can speak the true name of a creature you can see. For 1 minute, that creature has Disadvantage on saving throws against your spells and other effects. Curse: while you are attuned to the blade, you can't attune to another weapon, and each dawn you forget your own name until someone speaks it to you. Destroying the Blade: the blade breaks if a creature speaks the blade's own true name, which only the smith who forged it ever knew. When the blade breaks, every name it holds is freed, and the creatures it killed can be returned to life in the normal ways."),
("The Ninth Key", "Wondrous Item", "Artifact", A, "This key of pale gold opens doors that are not doors. Every Lock: while you hold it, you can open any lock, bar, or magical seal you touch, as if with the Knock spell, but silently. Doors Between: once per dawn, you can cast Plane Shift from the key. Once per 7 days, you can turn the key in the air to cast Gate from it. Curse: each time you use Gate, roll a d20. On a 1, something from the other side comes through as well, and it is not friendly. Destroying the Key: the key can be destroyed only by locking the last door it opened with the key itself, from the far side."),
]
